const checks=[];
function A(n,c){checks.push({name:n, ok:!!c});}
A('C.场景图工件存在 edited.png', fs.existsSync(D+'\\edited.png'));
A('C.成片工件存在 final.mp4', fs.existsSync(D+'\\final.mp4'));
